#!/usr/bin/env node
/**
 * Regenerate js/modules/translations.js from content/translations/*.json.
 *
 * The JSON files are the source of truth. The .js file is a build artifact
 * — committed so the browser can `import` it synchronously, never edited
 * by hand. Adding/editing a translation:
 *   1. Edit content/translations/<lang>.json
 *   2. Run `npm run build-translations` (also runs in prebuild)
 *   3. Commit both the JSON and the regenerated translations.js
 *
 * Ordering of languages in supportedLanguages is read from
 * content/translations/_order.json (controls UI dropdown order).
 */
import { readFileSync, writeFileSync, readdirSync } from 'node:fs';
import { join } from 'node:path';
import { fileURLToPath } from 'node:url';

const ROOT  = fileURLToPath(new URL('../../', import.meta.url));
const DIR   = join(ROOT, 'content', 'translations');
const ORDER = join(DIR, '_order.json');
const OUT   = join(ROOT, 'js', 'modules', 'translations.js');

const order = JSON.parse(readFileSync(ORDER, 'utf8'));
const filesInDir = new Set(readdirSync(DIR).filter(f => f.endsWith('.json') && !f.startsWith('_')).map(f => f.replace(/\.json$/, '')));

const orphan  = [...filesInDir].filter(l => !order.includes(l));
const missing = order.filter(l => !filesInDir.has(l));
if (orphan.length)  throw new Error('language files not in _order.json: ' + orphan.join(', '));
if (missing.length) throw new Error('langs in _order.json with no file: ' + missing.join(', '));

const translations = {};
for (const lang of order) {
  translations[lang] = JSON.parse(readFileSync(join(DIR, lang + '.json'), 'utf8'));
}

const banner = `/**
 * AUTO-GENERATED by .github/scripts/build-translations.mjs from
 * content/translations/*.json. Do not edit by hand. Edit the JSON
 * files and run \`npm run build-translations\` (also runs in prebuild).
 */
`;

const body = banner +
  'export const translations = ' + JSON.stringify(translations, null, 2) + ';\n\n' +
  'export const supportedLanguages = Object.keys(translations);\n\n' +
  'export function getTranslation(key, lang = \'en\') {\n' +
  '  return translations[lang]?.[key] || translations[\'en\'][key] || key;\n' +
  '}\n';

writeFileSync(OUT, body, 'utf8');
console.log(`Wrote ${OUT} (${order.length} languages)`);
